struct Builder {
    hir: HirModule,
    params: HashMap<String, Vec<f32>>,
    i64_params: HashMap<String, Vec<i64>>,
    env: HashMap<String, HirNodeId>,
}

impl Builder {
    fn new() -> Self {
        Self {
            hir: HirModule::new("ppocrv6_tiny_det_rlx"),
            params: HashMap::new(),
            i64_params: HashMap::new(),
            env: HashMap::new(),
        }
    }
    fn m(&mut self) -> HirMut<'_> {
        HirMut::new(&mut self.hir)
    }
    fn bind(&mut self, name: &str, id: HirNodeId) {
        self.env.insert(name.to_string(), id);
    }
    fn tensor(&self, name: &str) -> Result<HirNodeId> {
        self.env
            .get(name)
            .copied()
            .with_context(|| format!("tensor {:?}", name))
    }
    fn bind_param(&mut self, key: &str, shape: &[usize], data: Vec<f32>) -> HirNodeId {
        let id = HirMut::new(&mut self.hir).param(key, Shape::new(shape, DType::F32));
        self.params.insert(key.to_string(), data);
        id
    }
    fn bind_param_i64(&mut self, key: &str, shape: &[usize], data: Vec<i64>) -> HirNodeId {
        let id = HirMut::new(&mut self.hir).param(key, Shape::new(shape, DType::I64));
        self.i64_params.insert(key.to_string(), data);
        id
    }
}

